  'This is a harmless capability test. Do NOT read, write, or edit any files. Do NOT access the network. Simply compute 2 + 2 and return it. Respond only with the structured output: sum=4 and a short note confirming no files or network were touched.',
  { label: 'trivial-sum', phase: 'Probe', schema: SCHEMA }
)

log(`Probe complete: sum=${result?.sum}`)
return result

